final class METCustInterestNoteDP_Extension
{

}

Method.Source:
    /// <summary>
    /// MPJ_13531_CustReportLogos
    /// </summary>
    /// <param name = "_custInterestJour">Interest journal header</param>
    public void initTempTableFromCompanyInfo(custInterestJour _custInterestJour)
    {
        next initTempTableFromCompanyInfo(_custInterestJour);

        METIndustryKey industryKey = METCustTable::find(_custInterestJour.AccountNum).IndustryKey;
        container reportDesignNameContainer = SrsReportRunUtil::getReportAndDesignName(ssrsReportStr(METCustInterestNote, Report));

        if (industryKey && conLen(reportDesignNameContainer) >= 2)
        {
            SysDocuBrandDetails docuBrandDetails = SysDocuBrandDetails::findByRepNameAndIndKey(conPeek(reportDesignNameContainer, 1), conPeek(reportDesignNameContainer, 2), industryKey);

            if (docuBrandDetails)
            {
                if (docuBrandDetails.Image1Name)
                {
                    custInterestNoteTmp.Image = SysDocuBrandImages::getImage(docuBrandDetails.Image1Name);
                }
            }
        }
    }
